    },
    {
      "benefit": "IP",
      "years": [2019, 2022],
      "pattern": "drift",
      "direction": "increase",
      "magnitude": "~+0.05/yr, peaks at A/E 1.20",
      "confidence": 0.8,
      "evidence": [
        "ae_ip_by_year.csv shows consistent YoY rise from 1.04 (2019) to 1.20 (2022); reverts to ~0.93 in 2023-2024. Sustained upward trend over 4 years."
      ],
      "recommended_action": "Investigate IP claims development (e.g., definition creep, economic conditions delaying recovery, claims handling lag); review IP run-off and termination assumptions; track reversion to baseline."
    }
  ]
}

